/**
 * pytest exporter.
 *
 * For every table one test module that
 *   - checks that every generated row satisfies the schema
 *   - checks that the boundary rows (values sitting exactly on a declared
 *     limit) satisfy the schema too
 *   - turns every negative case into a parametrised test that *must* be
 *     rejected, and asserts which schema keyword reported the violation
 *
 * The validator is shipped next to the tests, so the suite runs with nothing
 * but pytest installed.
 */
import { pyLiteral, slug } from './common.js';
export function exportPytest(data) {
    const files = [{ path: 'pytest/_validator.py', content: validatorModule() }];
    for (const view of data.views) {
        const negatives = data.negatives.filter((negative) => negative.table === view.name);
        const boundaries = data.boundaries.filter((boundary) => boundary.table === view.name);
        files.push({
            path: 'pytest/test_' + slug(view.name) + '.py',
            content: testModule(view, negatives, boundaries, data),
        });
    }
    files.push({ path: 'pytest/README.md', content: readme(data) });
    return files;
}
/** One test module. */
function testModule(view, negatives, boundaries, data) {
    const lines = [];
    lines.push('"""Generated by schemaseed — do not edit by hand.');
    lines.push('');
    lines.push('Table: ' + view.name);
    lines.push('Mode: ' + data.mode);
    lines.push('Seed: ' + data.seed);
    lines.push('"""');
    lines.push('');
    lines.push('import pytest');
    lines.push('');
    lines.push('from _validator import ValidationError, validate');
    lines.push('');
    lines.push('SCHEMA = ' + pyLiteral(view.schema));
    lines.push('');
    lines.push('VALID_ROWS = ' + pyLiteral(view.rows));
    lines.push('');
    lines.push('BOUNDARY_ROWS = ' +
        pyLiteral(boundaries.map((boundary) => ({
            kind: boundary.kind,
            data: boundary.data,
        }))));
    lines.push('');
    lines.push('NEGATIVE_CASES = [');
    for (const negative of negatives) {
        lines.push('    pytest.param(');
        lines.push('        {');
        lines.push('            "kind": ' + pyLiteral(negative.kind) + ',');
        lines.push('            "reason": ' + pyLiteral(negative.reason) + ',');
        lines.push('            "keyword": ' + pyLiteral(negative.keyword ?? 'type') + ',');
        lines.push('            "property": ' + pyLiteral(negative.property ?? '') + ',');
        lines.push('            "data": ' + pyLiteral(negative.data) + ',');
        lines.push('        },');
        lines.push('        id=' + pyLiteral(negative.kind + ':' + (negative.property ?? '')) + ',');
        lines.push('    ),');
    }
    lines.push(']');
    lines.push('');
    lines.push('');
    lines.push('def test_valid_rows_are_accepted():');
    lines.push('    """Every row generated from the schema has to satisfy it."""');
    lines.push('    for index, row in enumerate(VALID_ROWS):');
    lines.push('        validate(SCHEMA, row)');
    lines.push('');
    lines.push('');
    lines.push('def test_boundary_rows_are_accepted():');
    lines.push('    """Values sitting exactly on a declared limit are still valid."""');
    lines.push('    for index, row in enumerate(BOUNDARY_ROWS):');
    lines.push('        validate(SCHEMA, row["data"])');
    lines.push('');
    lines.push('');
    lines.push('@pytest.mark.parametrize("case", NEGATIVE_CASES)');
    lines.push('def test_negative_cases_are_rejected(case):');
    lines.push('    """Each negative case has to break the schema it was derived from."""');
    lines.push('    with pytest.raises(ValidationError) as excinfo:');
    lines.push('        validate(SCHEMA, case["data"])');
    lines.push('    expected = " %s: " % case["keyword"]');
    lines.push('    assert expected in str(excinfo.value), (');
    lines.push('        "expected the %r keyword to be reported for %r, got: %s"');
    lines.push('        % (case["keyword"], case["property"], excinfo.value)');
    lines.push('    )');
    lines.push('');
    lines.push('');
    lines.push('def test_negative_cases_exist():');
    lines.push('    """The generator has to cover the family of violations."""');
    lines.push('    kinds = {case["kind"] for case in NEGATIVE_CASES}');
    lines.push('    assert kinds, "no negative case was generated for ' + view.name + '"');
    lines.push('');
    return lines.join('\n');
}
/** A short note describing the generated suite. */
function readme(data) {
    const lines = [];
    lines.push('# Generated pytest suite');
    lines.push('');
    lines.push('Seed: ' + data.seed + ' — mode: ' + data.mode);
    lines.push('');
    lines.push('Run it with:');
    lines.push('');
    lines.push('```');
    lines.push('pytest pytest/');
    lines.push('```');
    lines.push('');
    lines.push('The suite is self contained: `_validator.py` implements the JSON Schema');
    lines.push('keywords the generated data uses, so only pytest is needed.');
    lines.push('');
    for (const view of data.views) {
        const negatives = data.negatives.filter((negative) => negative.table === view.name);
        const kinds = [...new Set(negatives.map((negative) => negative.kind))].sort();
        lines.push('- `test_' +
            slug(view.name) +
            '.py`: ' +
            view.rows.length +
            ' valid rows, ' +
            negatives.length +
            ' negative cases (' +
            (kinds.join(', ') || 'none') +
            ')');
    }
    lines.push('');
    return lines.join('\n');
}
/** The validator that ships with the generated tests. */
function validatorModule() {
    return String.raw `"""Minimal JSON Schema validator, generated by schemaseed.

It implements the keywords the generated data actually uses: type, required,
properties, enum, const, format, minLength, maxLength, pattern, minimum,
maximum, exclusiveMinimum, exclusiveMaximum, multipleOf, items, minItems,
maxItems, uniqueItems, nullable and oneOf/anyOf.
"""

import datetime
import re

__all__ = ["ValidationError", "validate", "collect_errors"]


class ValidationError(Exception):
    """Raised when a payload does not satisfy its schema."""


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _type_matches(value, expected):
    if expected == "object":
        return isinstance(value, dict)
    if expected == "array":
        return isinstance(value, list)
    if expected == "string":
        return isinstance(value, str)
    if expected == "integer":
        return _is_int(value)
    if expected == "number":
        return _is_int(value) or isinstance(value, float)
    if expected == "boolean":
        return isinstance(value, bool)
    if expected == "null":
        return value is None
    return True


def _valid_date(text):
    try:
        datetime.date.fromisoformat(text)
        return True
    except ValueError:
        return False


def _valid_time(text):
    try:
        datetime.time.fromisoformat(text.replace("Z", ""))
        return True
    except ValueError:
        return False


def _valid_datetime(text):
    try:
        datetime.datetime.fromisoformat(text.replace("Z", "+00:00"))
        return True
    except ValueError:
        return False


def _valid_ipv4(text):
    parts = text.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit() or len(part) > 3 or not 0 <= int(part) <= 255:
            return False
    return True


def _valid_ipv6(text):
    if ":" not in text:
        return False
    return re.fullmatch(r"[0-9A-Fa-f:]+", text) is not None


def _valid_email(text):
    return re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", text) is not None


def _valid_uri(text):
    return re.match(r"^[A-Za-z][A-Za-z0-9+.\-]*:", text) is not None


def _valid_hostname(text):
    if not text or len(text) > 253:
        return False
    for label in text.split("."):
        if not label or len(label) > 63:
            return False
        if re.fullmatch(r"[A-Za-z0-9]([A-Za-z0-9\-]*[A-Za-z0-9])?", label) is None:
            return False
    return True


FORMAT_CHECKS = {
    "email": _valid_email,
    "idn-email": _valid_email,
    "uuid": lambda text: re.fullmatch(
        r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}",
        text,
    )
    is not None,
    "date": _valid_date,
    "date-time": _valid_datetime,
    "time": _valid_time,
    "uri": _valid_uri,
    "url": _valid_uri,
    "uri-reference": lambda text: True,
    "hostname": _valid_hostname,
    "ipv4": _valid_ipv4,
    "ipv6": _valid_ipv6,
}


def collect_errors(schema, data, path="$"):
    """Return every way in which *data* breaks *schema*."""
    errors = []
    _validate(schema, data, path, errors)
    return errors


def validate(schema, data, path="$"):
    """Raise ValidationError when *data* does not satisfy *schema*."""
    errors = collect_errors(schema, data, path)
    if errors:
        raise ValidationError("; ".join(errors))
    return data


def _validate(schema, data, path, errors):
    if schema is True or schema is None:
        return
    if schema is False:
        errors.append("%s: type: no value is allowed here" % path)
        return
    if not isinstance(schema, dict):
        return

    if "const" in schema and data != schema["const"]:
        errors.append("%s: const: expected %r" % (path, schema["const"]))

    if "enum" in schema and data not in schema["enum"]:
        errors.append("%s: enum: %r is not one of %r" % (path, data, schema["enum"]))

    expected = schema.get("type")
    types = expected if isinstance(expected, list) else ([expected] if expected is not None else [])
    nullable = schema.get("nullable") is True or "null" in types

    if data is None:
        if not nullable:
            if types:
                errors.append(
                    "%s: type: expected %s, got NoneType" % (path, " or ".join(types))
                )
            else:
                errors.append("%s: type: null is not allowed" % path)
        return

    if types and not any(_type_matches(data, expected_type) for expected_type in types):
        errors.append(
            "%s: type: expected %s, got %s"
            % (path, " or ".join(types), type(data).__name__)
        )
        return

    if isinstance(data, str):
        fmt = schema.get("format")
        check = FORMAT_CHECKS.get(fmt) if isinstance(fmt, str) else None
        if check is not None and not check(data):
            errors.append("%s: format: %r is not a valid %s" % (path, data, fmt))
        if "minLength" in schema and len(data) < schema["minLength"]:
            errors.append(
                "%s: minLength: %d characters is shorter than %d"
                % (path, len(data), schema["minLength"])
            )
        if "maxLength" in schema and len(data) > schema["maxLength"]:
            errors.append(
                "%s: maxLength: %d characters is longer than %d"
                % (path, len(data), schema["maxLength"])
            )
        pattern = schema.get("pattern")
        if isinstance(pattern, str) and re.search(pattern, data) is None:
            errors.append("%s: pattern: %r does not match %r" % (path, data, pattern))

    if isinstance(data, bool):
        pass
    elif isinstance(data, (int, float)):
        if "minimum" in schema and data < schema["minimum"]:
            errors.append("%s: minimum: %r is below %r" % (path, data, schema["minimum"]))
        if "maximum" in schema and data > schema["maximum"]:
            errors.append("%s: maximum: %r is above %r" % (path, data, schema["maximum"]))
        exclusive_min = schema.get("exclusiveMinimum")
        if (
            isinstance(exclusive_min, (int, float))
            and not isinstance(exclusive_min, bool)
            and data <= exclusive_min
        ):
            errors.append(
                "%s: exclusiveMinimum: %r is not above %r" % (path, data, exclusive_min)
            )
        exclusive_max = schema.get("exclusiveMaximum")
        if (
            isinstance(exclusive_max, (int, float))
            and not isinstance(exclusive_max, bool)
            and data >= exclusive_max
        ):
            errors.append(
                "%s: exclusiveMaximum: %r is not below %r" % (path, data, exclusive_max)
            )
        step = schema.get("multipleOf")
        if isinstance(step, (int, float)) and not isinstance(step, bool) and step > 0:
            quotient = data / step
            if abs(quotient - round(quotient)) > 1e-9:
                errors.append(
                    "%s: multipleOf: %r is not a multiple of %r" % (path, data, step)
                )

    if isinstance(data, list):
        if "minItems" in schema and len(data) < schema["minItems"]:
            errors.append(
                "%s: minItems: %d items is fewer than %d"
                % (path, len(data), schema["minItems"])
            )
        if "maxItems" in schema and len(data) > schema["maxItems"]:
            errors.append(
                "%s: maxItems: %d items is more than %d" % (path, len(data), schema["maxItems"])
            )
        if schema.get("uniqueItems") is True:
            seen = []
            for item in data:
                if item in seen:
                    errors.append("%s: uniqueItems: %r appears twice" % (path, item))
                    break
                seen.append(item)
        items = schema.get("items")
        if isinstance(items, dict):
            for index, item in enumerate(data):
                _validate(items, item, "%s[%d]" % (path, index), errors)

    if isinstance(data, dict):
        for name in schema.get("required") or []:
            if name not in data:
                errors.append("%s: required: missing property %r" % (path, name))
        properties = schema.get("properties") or {}
        for name, value in data.items():
            if name in properties:
                _validate(properties[name], value, "%s.%s" % (path, name), errors)

    branches = schema.get("oneOf") or schema.get("anyOf")
    if isinstance(branches, list) and branches:
        if not any(not collect_errors(branch, data, path) for branch in branches):
            errors.append("%s: oneOf: %r does not match any branch" % (path, data))
`;
}
